uv run python -c 'import sys,tempfile; from pathlib import Path; sys.path[:0]=["tests"]; import test_trust_mutants as T; r=Path(tempfile.mkdtemp())/"p"; T.scaffold(r,""); (r/"lean/Demo/Defs.lean").write_text("namespace Demo\n\ndef fastSmall (n : Nat) : Bool := n < 3\n\ntheorem fastSmall_iff (n : Nat) : fastSmall n = true ↔ n < 3 := by\n  simp [fastSmall]\n\ndef Small (n : Nat) : Prop := n < 3\n\ninstance (n : Nat) : Decidable (Small n) := decidable_of_iff _ (fastSmall_iff n)\n\nstructure Ver where\n  v : Nat\n\ninstance : Repr Ver := ⟨fun x _ => if Small x.v then \"small\" else \"big\"⟩\n\n/-- info: (true, small) -/\n#guard_msgs in\n#eval! (fastSmall 7 == fastSmall 7, (⟨2⟩ : Ver))\n\nend Demo\n"); T.dump(r,Path(tempfile.mkdtemp()),[]); T.git(r,"add","."); T.git(r,"commit","-qm","head"); s=[(m["operator"],m["status"],m["detail"][:90]) for m in T.of(T.tool(r,r.parent/"run")[1],"fastSmall")]; print(s); assert s and not any(x=="KILLED" for _,x,_ in s), s'
